    for r in range(m["rows"]):
        for c in range(m["cols"]):
            if len(colors) >= m["cnt"]: break
            colors.append(arr[r*fh:(r+1)*fh, c*fw:(c+1)*fw].mean(axis=(0,1)))
fc = np.array(colors)
print("Side to Side: dur=%ds, %d frames every %dms" % (m["dur"], len(fc), m["interval"]))
for i in range(12): print(f"  t={i*2}s rgb={fc[i].round(0).astype(int)}")
