i0=int(0.55*len(fc)); 
for i in range(i0,i0+6): print(f"  t={i*2}s rgb={fc[i].round(0).astype(int)}")
print("  ... last frames:")
for i in range(len(fc)-6,len(fc)): print(f"  t={i*2}s rgb={fc[i].round(0).astype(int)}")
EOF

